tool_input.command:
$f='D:\repository\门户H5\src\pages\systems\index.vue'
$lines = Get-Content $f -Encoding UTF8
$target = '      <AppHeader title="" :back="true" @back="back" />'
foreach ($l in $lines) {
  if ($l -like '*AppHeader*') { Write-Output ("APP len=" + $l.Length + " eq=" + ($l -eq $target) + " :: [" + $l + "]") }
}
foreach ($l in $lines) {
  if ($l -like '*home/index*') { Write-Output ("BACK :: [" + $l + "]") }
}

$f='D:\repository\门户H5\src\pages\systems\index.vue'
$lines = Get-Content $f -Encoding UTF8
$out = @()
$skipNext = 0
foreach ($l in $lines) {
  if ($skipNext -gt 0) { $skipNext--; continue }
  if ($l -eq '    <AppHeader title="" :back="true" @back="back" />') {
    $out += '    <AppHeader title="应用列表" :back="true" @back="back" />'
    $skipNext = 4
    continue
  }
  if ($l -eq "  else uni.reLaunch({ url: '/pages/home/index' })") {
    $out += "  else uni.reLaunch({ url: '/pages/login-design/index' })"
    continue
  }
  $out += $l
}
[System.IO.File]::WriteAllText($f, ($out -join "`n") + "`n")
Write-Output "done"

try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:8091/api/v3.0/portal/appLogin/captcha" -Method Post -UseBasicParsing -TimeoutSec 10
  $body = $r.Content
  Write-Output ("HTTP " + $r.StatusCode + " len=" + $body.Length)
  Write-Output ($body.Substring(0, [math]::Min(120, $body.Length)))
} catch {
  Write-Output ("ERR: " + $_.Exception.Message)
}

